def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        q = (y + dy, x + dx)
                        if (dy or dx) and 0 <= q[0] < h and 0 <= q[1] < w and grid[q[0]][q[1]] != 0 and q not in seen:
                            seen.add(q)
                            stack.append(q)
            components.append(comp)
    comp = min(components, key=len)
    r0 = min(r for r, c in comp); r1 = max(r for r, c in comp)
    c0 = min(c for r, c in comp); c1 = max(c for r, c in comp)
    return [[grid[r][c] if (r, c) in set(comp) else 0 for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]

